extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var launcher_script: GDScript = load("res://game_launcher.gd")
	if check("launcher_exists", launcher_script != null, "Lo script game_launcher.gd deve caricarsi senza errori"):
		var launcher = launcher_script.new()
		if check("launcher_method", has_function(launcher, "load_systems_map"), "game_launcher.gd deve avere load_systems_map()"):
			var map_data: Dictionary = call_if_exists(launcher, "load_systems_map", [], {})
			check("map_loaded", not map_data.is_empty() and map_data.has("systems"), "load_systems_map() deve caricare res://core/systems_map.json")

	var settings_script: GDScript = load("res://settings_saver.gd")
	if check("settings_exists", settings_script != null, "Lo script settings_saver.gd deve caricarsi senza errori"):
		var saver = settings_script.new()
		if check("saver_method", has_function(saver, "save_user_settings"), "settings_saver.gd deve avere save_user_settings()"):
			var ok: bool = call_if_exists(saver, "save_user_settings", [{"volume": 80}], false)
			check("save_ok", ok, "save_user_settings() deve restituire true")
			check("user_settings_created", FileAccess.file_exists("user://settings.cfg"), "Il file di configurazione deve trovarsi in user://settings.cfg")

