class_name GameLauncher
extends RefCounted


func load_systems_map() -> Dictionary:
	# Percorso con maiuscole errare
	var path := "res://Core/Systems_Map.json"
	if not FileAccess.file_exists(path):
		return {}
	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		return {}
	var json_data: Variant = JSON.parse_string(file.get_as_text())
	if json_data is Dictionary:
		return json_data
	return {}

class_name SettingsSaver
extends RefCounted


func save_user_settings(settings_data: Dictionary) -> bool:
	# Tentativo di scrittura illegale in res:// nel gioco esportato
	var path := "res://settings.cfg"
	var config := ConfigFile.new()
	for key in settings_data:
		config.set_value("settings", key, settings_data[key])
	var err := config.save(path)
	return err == OK

